window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[108]={"id":"108","numero":108,"titre":"Item 108 — Confusion, démence du sujet âgé","objectifs":[{"id":"108-1","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Comprendre le mécanisme physiopathologique de la confusion mentale","contenu":"<p>La physiopathologie de la <span class=\"kw-clinique\">confusion</span> mentale est complexe et en grande partie méconnue. Point capital : <span class=\"kw-alerte\">aucune lésion anatomopathologique spécifique</span> n'a été mise en évidence — ce qui l'oppose radicalement à la démence. Deux familles de mécanismes sont retenues : les <span class=\"kw-def\">modifications de la neurotransmission</span> et les processus inflammatoires.</p>\n      <p><strong>Modifications de la neurotransmission</strong> — plusieurs systèmes sont atteints simultanément :</p>\n      <table >\n        <thead><tr><th>Système</th><th>Anomalie et rôle</th></tr></thead>\n        <tbody>\n          <tr><td>Acétylcholine</td><td><strong>Anomalie :</strong> <span class=\"kw-alerte\">déficit en acétylcholine</span> <br><strong>Rôle :</strong> l'acétylcholine est clé dans les processus attentionnels et la cognition — son déficit est considéré comme central</td></tr>\n          <tr><td>Dopamine</td><td><strong>Anomalie :</strong> <span class=\"kw-bio\">hypersécrétion de dopamine</span> <br><strong>Effet :</strong> participe à la désorganisation de la pensée</td></tr>\n          <tr><td>Sérotonine</td><td><strong>Anomalie :</strong> <span class=\"kw-bio\">déséquilibre sérotoninergique</span> également évoqué</td></tr>\n          <tr><td>Métabolisme oxydatif</td><td>L'atteinte du système cholinergique est évoquée par son implication dans la diminution du métabolisme cérébral oxydatif</td></tr>\n          <tr><td>Cortisol</td><td>Lors d'un <span class=\"kw-alerte\">stress aigu</span>, l'<span class=\"kw-bio\">élévation du cortisol</span> pourrait précipiter ou entretenir le <span class=\"kw-def\">syndrome confusionnel</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Processus inflammatoires</strong> — secondaires aux <span class=\"kw-etio\">traumatismes</span>, aux <span class=\"kw-etio\">infections</span> ou à la <span class=\"kw-etio\">chirurgie</span>, médiés par les <span class=\"kw-bio\">cytokines pro-inflammatoires</span> :</p>\n      <ul>\n        <li>Responsables d'une <span class=\"kw-def\">réponse exagérée de la microglie</span> aboutissant à une <span class=\"kw-alerte\">inflammation cérébrale</span>.</li>\n        <li>Les <span class=\"kw-bio\">marqueurs d'inflammation</span> (<span class=\"kw-bio\">interleukines</span>) interfèrent avec la production et le relargage des neurotransmetteurs.</li>\n        <li>Ils exercent par ailleurs un <span class=\"kw-alerte\">effet neurotoxique direct</span>.</li>\n      </ul>","frequence":0},{"id":"108-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une confusion et d’une démence","contenu":"<p>Deux entités à distinguer formellement — c'est un piège classique de l'EDN.</p>\n      <p><span class=\"kw-def\">Confusion mentale (syndrome confusionnel)</span> : <span class=\"kw-def\">altération modérée de la vigilance</span> entraînant une désorganisation globale de la pensée et des fonctions cognitives. L'<span class=\"kw-clinique\">attention</span> est la « porte d'entrée » du fonctionnement cognitif : si elle est entrebâillée ou fermée, toutes les fonctions intellectuelles qui en dépendent sont perturbées. Enchaînement : <span class=\"kw-clinique\">altération de la vigilance</span> → <span class=\"kw-clinique\">troubles attentionnels</span> → <span class=\"kw-clinique\">confusion</span> mentale.</p>\n      <p><span class=\"kw-def\">Démence (trouble neurocognitif majeur)</span> : syndrome défini par la présence des <span class=\"kw-chiffre\">deux</span> critères suivants :</p>\n      <ul>\n        <li><span class=\"kw-def\">Altération durable</span> d'<span class=\"kw-chiffre\">≥ 1</span> fonction cognitive antérograde (mémoire, attention, langage, jugement…) et/ou comportementale (personnalité, affects, conduites sociales).</li>\n        <li><span class=\"kw-alerte\">Altération de l'autonomie</span> dans la vie quotidienne, induite par la sévérité des troubles.</li>\n      </ul>\n      <p>Cliniquement, le syndrome démentiel est un <span class=\"kw-def\">trouble chronique de plus de 6 mois</span>, <span class=\"kw-clinique\">sans grande variation nycthémérale</span>, fait de troubles cognitifs spécifiques. Physiopathologiquement il repose sur des <span class=\"kw-alerte\">lésions structurelles</span> de circuits cérébraux ; la <span class=\"kw-clinique\">confusion</span>, elle, est liée à un simple trouble de la vigilance sans lésion.</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-clinique\">Confusion</span></th><th>Démence</th></tr></thead>\n        <tbody>\n          <tr><td>Installation</td><td><span class=\"kw-clinique\">Aiguë</span></td><td><span class=\"kw-clinique\">Progressive</span></td></tr>\n          <tr><td>Fluctuation</td><td><span class=\"kw-clinique\">Caractéristique</span></td><td><span class=\"kw-clinique\">Absente</span></td></tr>\n          <tr><td>Évolution</td><td><span class=\"kw-clinique\">Réversible</span></td><td><span class=\"kw-alerte\">Irréversible</span></td></tr>\n          <tr><td>Lésions cérébrales</td><td>Absentes</td><td><span class=\"kw-alerte\">Présentes</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À ne pas confondre — vieillissement cognitif normal :</strong> il peut entraîner un trouble cognitif léger qui <span class=\"kw-alerte\">n'entrave jamais l'autonomie</span> (pas de retentissement ADL/IADL) ; il touche surtout les <span class=\"kw-clinique\">fonctions exécutives</span> (↘ flexibilité de la pensée, ↘ vitesse de traitement, ↘ attention divisée). Les tests psychométriques rendus au clinicien sont ajustés à l'âge et au niveau d'éducation.</div>\n      <div class=\"callout callout-info\">Une <span class=\"kw-clinique\">confusion</span> mentale peut <strong>révéler ou émailler l'évolution</strong> d'un syndrome démentiel : les deux ne s'excluent pas. Tout épisode confusionnel impose de réévaluer l'état cognitif à distance.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 343 — Etat confusionnel - trouble de conscience · 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":1},{"id":"108-3","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes neurologiques de confusion mentale","contenu":"<p>Les causes neurologiques de <span class=\"kw-clinique\">confusion</span> sont moins fréquentes que les causes non neurologiques chez le sujet âgé, mais elles sont souvent <span class=\"kw-alerte\">graves et urgentes</span> : leur recherche conditionne le pronostic.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr><td>Hémorragie méningée</td><td><span class=\"kw-etio\">Hémorragie sous-arachnoïdienne</span> ; <span class=\"kw-alerte\">urgence vitale</span> à évoquer devant <span class=\"kw-clinique\">céphalée</span> brutale + confusion</td></tr>\n          <tr><td>Méningites et méningo-encéphalites</td><td>Origine <span class=\"kw-etio\">bactérienne</span> ; virale ; parasitaire (neuropaludisme) ; à prions</td></tr>\n          <tr><td>Processus expansifs intracrâniens</td><td><span class=\"kw-etio\">Tumeurs</span> ; abcès cérébraux ; hématomes</td></tr>\n          <tr><td>Traumatisme crânien</td><td><span class=\"kw-etio\">Hématome sous-dural</span> ; hématome extra-dural ; hématome intraparenchymateux</td></tr>\n          <tr><td>Infarctus cérébraux</td><td>Localisés au <span class=\"kw-clinique\">tronc cérébral</span>, aux ganglions de la base, ou infarctus de grande taille</td></tr>\n          <tr><td><span class=\"kw-etio\">Épilepsie</span> généralisée</td><td><span class=\"kw-clinique\">Phase post-critique</span> ou <span class=\"kw-alerte\">état de mal épileptique</span></td></tr>\n          <tr><td>Pathologie neurologique chronique décompensée</td><td><span class=\"kw-etio\">SEP</span> ; <span class=\"kw-etio\">maladie de Parkinson</span> ; <span class=\"kw-etio\">maladie d'Alzheimer</span> — décompensées par un stress physique (<span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-clinique\">fièvre</span>…)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 341 — Hémorragie méningée · 151 — <span class=\"kw-def\">Méningite</span> - méningoencéphalite · 105 — Epilepsie · 340 — <span class=\"kw-def\">AVC</span> · 104 — SEP · 106 — Parkinson</em></p>","frequence":0},{"id":"108-4","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes non neurologiques de confusion mentale","contenu":"<p>Chez la personne âgée, les causes non neurologiques sont les <strong>plus fréquentes</strong>. Elles sont volontiers <span class=\"kw-alerte\">multiples et intriquées</span>. Cinq grandes catégories :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Toxiques</td><td><strong><span class=\"kw-etio\">Alcool</span> :</strong> ivresse aiguë ; <span class=\"kw-alerte\">sevrage</span> (risque de delirium tremens) <br><strong>Drogues :</strong> héroïne ; cocaïne <br><strong>Toxiques industriels :</strong> pesticides ; solvants ; <span class=\"kw-etio\">intoxication au CO</span> <br><strong>Médicaments :</strong> <span class=\"kw-ttt\">psychotropes</span> (BZD ; antidépresseurs ; neuroleptiques ; <span class=\"kw-ttt\">lithium</span> ; antiépileptiques ; <span class=\"kw-ttt\">opioïdes</span>) ; <span class=\"kw-ttt\">anti-parkinsoniens</span> ; <span class=\"kw-ci\">anticholinergiques</span> <br><strong>Piège :</strong> le <span class=\"kw-alerte\">sevrage brutal d'un psychotrope</span> est lui-même confusiogène</td></tr>\n          <tr><td>Métaboliques</td><td><strong>Hydro-électrolytiques :</strong> <span class=\"kw-bio\">hyper/hyponatrémie</span> ; hypokaliémie ; hypercalcémie ; déshydratation <br><strong>Glycémie :</strong> <span class=\"kw-bio\">hypoglycémie</span> <br><strong>Endocrinopathies :</strong> <span class=\"kw-alerte\">décompensation</span> d'un <span class=\"kw-def\">diabète</span> ; insuffisance surrénale aiguë ; <span class=\"kw-etio\">hypothyroïdie</span> ; insuffisance antéhypophysaire aiguë <br><strong>Insuffisances d'organe :</strong> rénale ; hépatique ; cardio-respiratoire <br><strong>Carences :</strong> <span class=\"kw-bio\">vitamine B1</span> (Gayet-Wernicke, Korsakoff) ; vitamine B3 (pellagre) ; Marchiafava-Bignami ; B9 / B12</td></tr>\n          <tr><td>Infectieuses</td><td><span class=\"kw-etio\">Infections urinaires</span> ; infections pulmonaires ; <span class=\"kw-alerte\">toute fièvre</span>, d'autant plus s'il existe une détérioration cognitive préalable</td></tr>\n          <tr><td>Facteurs de risque du sujet âgé</td><td><span class=\"kw-clinique\">Fécalome</span> ; <span class=\"kw-clinique\">globe vésical</span> ; douleur ; troubles neurosensoriels ; immobilisation ; polymédication</td></tr>\n          <tr><td>Autres</td><td>Hypothermie ; hypoxie / anoxie cérébrale (<span class=\"kw-alerte\">arrêt cardiaque</span>, <span class=\"kw-alerte\">état de choc</span>) ; post-opératoire ; causes intriquées (alcool + médicaments ± traumatisme crânien)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">Chez le sujet âgé, penser aux <strong>causes simples mais classiques</strong> : un fécalome ou un globe vésical non recherchés sont des causes fréquentes et facilement réversibles de <span class=\"kw-clinique\">confusion</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 240 — Hypoglycémie · 247 — <span class=\"kw-def\">Diabète</span> · 243 — <span class=\"kw-etio\">Hypothyroïdie</span> · 245 — Insuffisance surrénale</em></p>","frequence":0},{"id":"108-5","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir rechercher les causes de la confusion mentale","contenu":"<p>La recherche étiologique suit une démarche gériatrique en <span class=\"kw-chiffre\">2 étapes</span> : identifier les <span class=\"kw-def\">facteurs prédisposants</span> puis les <span class=\"kw-def\">facteurs précipitants</span>. Notion clé : plus la réserve cognitive est dégradée, moins le facteur précipitant a besoin d'être important pour déclencher la confusion.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>1 — Facteurs prédisposants</td><td><span class=\"kw-clinique\">Âge ≥ 80 ans</span> ; ATCD de confusion (notamment post-opératoire) ; TNCM ou troubles cognitifs chroniques ; immobilisation (aggravée par la contention) ; <span class=\"kw-clinique\">déficit sensoriel</span> visuel ou auditif ; comorbidités multiples ; dénutrition ; polymédication ; troubles de l'humeur (état dépressif)</td></tr>\n          <tr><td>2 — Facteurs précipitants</td><td>Souvent <span class=\"kw-alerte\">multiples</span> chez le sujet âgé ; leur correction représente souvent le <strong>seul traitement nécessaire</strong> à la guérison ; toute situation aiguë, <span class=\"kw-etio\">iatrogène</span> ou pathologique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan de 1ʳᵉ intention</strong> (systématique) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">SaO2</span> ; <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span> ; créatininémie ; <span class=\"kw-bio\">ionogramme</span> sanguin ; <span class=\"kw-bio\">calcémie</span> ; <span class=\"kw-bio\">glycémie</span> ; protides totaux ; <span class=\"kw-bio\">bandelette urinaire</span> ; <span class=\"kw-clinique\">ECG</span>.</li>\n        <li>Le CEN ajoute : <span class=\"kw-bio\">bilan hépatique</span> ; bilan d'hémostase ; <span class=\"kw-imagerie\">radiographie thoracique</span>.</li>\n      </ul>\n      <p><strong>Bilan selon le contexte</strong> :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication en 1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">TDM cérébrale</span></td><td><span class=\"kw-clinique\">Signe de localisation</span> ; suspicion d'<span class=\"kw-etio\">HSA</span> ; traumatisme crânien même mineur ; chute dans des circonstances peu claires</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Ponction lombaire</span></td><td><span class=\"kw-alerte\">Fièvre sans autre point d'appel</span> ; <span class=\"kw-def\">syndrome méningé</span> ; suspicion d'HSA (après <span class=\"kw-imagerie\">TDM</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">EEG</span></td><td>Suspicion de <span class=\"kw-etio\">confusion post-critique</span> d'une <span class=\"kw-etio\">épilepsie</span> ; dépistage d'épilepsies infracliniques si bilan négatif</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 343 — Etat confusionnel - trouble de conscience</em></p>","frequence":0},{"id":"108-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique d’un patient confus","contenu":"<p>La <span class=\"kw-clinique\">confusion</span> est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique</span> imposant une <span class=\"kw-alerte\">hospitalisation</span> : la cause est potentiellement grave et la <span class=\"kw-clinique\">confusion</span> elle-même est dangereuse.</p>\n      <p><strong>Démarche en 2 temps :</strong></p>\n      <ul>\n        <li>Évaluer le <span class=\"kw-clinique\">retentissement vital à court terme</span> (constantes) et <span class=\"kw-alerte\">traiter immédiatement les troubles vitaux</span> (ex. <span class=\"kw-alerte\">état de choc</span>).</li>\n        <li>Déterminer l'étiologie : le <span class=\"kw-def\">traitement étiologique est la priorité</span> — seul le traitement de la cause permet la guérison. En gériatrie, cela revient à corriger les <span class=\"kw-def\">facteurs précipitants</span>.</li>\n      </ul>\n      <p><strong>Mesures générales</strong> — à privilégier systématiquement :</p>\n      <ul>\n        <li>Supprimer les traitements non indispensables, surtout les <span class=\"kw-ttt\">psychotropes</span> — <span class=\"kw-alerte\">mais pas de sevrage brutal d'un psychotrope ancien</span> (le sevrage est lui-même confusiogène).</li>\n        <li>Diminuer la posologie des <span class=\"kw-ttt\">corticoïdes</span> ; maintenir <span class=\"kw-clinique\">hydratation et nutrition</span> (au besoin par voie parentérale) ; favoriser l'élimination (laxatifs, accès aux toilettes).</li>\n        <li><span class=\"kw-clinique\">Environnement calme</span>, sécurisant, suffisamment éclairé ; chambre individuelle ; visites limitées aux référents.</li>\n        <li>Lutter contre l'isolement sensoriel : prothèses auditives et lunettes ; maintenir une mobilité physique ; restaurer les repères spatio-temporels (calendrier, horloge).</li>\n      </ul>\n      <p><strong>Traitements symptomatiques</strong> — recours <span class=\"kw-alerte\">rare</span>, voie orale privilégiée :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Anxiété <strong>majeure</strong> uniquement</td><td><span class=\"kw-ttt\">BZD à demi-vie courte</span> à faible dose : <span class=\"kw-ttt\">oxazépam</span> ; <span class=\"kw-ttt\">alprazolam</span> <br><strong>À éviter :</strong> <span class=\"kw-ci\">hydroxyzine</span> ; <span class=\"kw-ci\">cyamémazine</span> ; <span class=\"kw-ci\">halopéridol</span> (composante anticholinergique)</td></tr>\n          <tr><td>Délire / hallucinations avec agitation menaçante</td><td><span class=\"kw-ttt\">Neuroleptique atypique</span> per os : <span class=\"kw-ttt\">rispéridone</span> ou <span class=\"kw-ttt\">olanzapine</span> <br><strong>Éviter</strong> les formes <span class=\"kw-ci\">injectables</span> ; <span class=\"kw-ttt\">tiapride IM</span> en dernier recours</td></tr>\n          <tr><td>Maladie à corps de Lewy / Parkinson</td><td>Neuroleptiques habituels <span class=\"kw-ci\">contre-indiqués</span> (risque de <span class=\"kw-alerte\">syndrome malin</span>) → <span class=\"kw-ttt\">quétiapine (hors AMM)</span> ou <span class=\"kw-ttt\">clozapine</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">La <strong>contention physique</strong> (barrières, attaches mousses, sangles) est une mesure de <span class=\"kw-alerte\">dernier recours</span> : sur prescription médicale engageant le prescripteur, durée limitée, réévaluation pluriquotidienne. Elle <span class=\"kw-alerte\">aggrave</span> agitation et angoisse.</div>\n      <div class=\"callout callout-info\"><strong>Évolution :</strong> la <span class=\"kw-clinique\">confusion</span> peut <span class=\"kw-alerte\">disparaître lentement</span>, même une fois la cause résolue — il faut être <strong>patient</strong> avant d'évaluer l'efficacité de la prise en charge.</div>","frequence":0},{"id":"108-7","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les principales lésions de la maladie d’Alzheimer (MA)","contenu":"<p><strong>Poids de la maladie :</strong> <span class=\"kw-def\">1ʳᵉ cause de démence</span> (&gt; <span class=\"kw-chiffre\">70 %</span> des démences dégénératives ; les maladies neurodégénératives = <span class=\"kw-chiffre\">70-90 %</span> des démences) ; <span class=\"kw-chiffre\">≈ 1 million</span> de personnes en France ; prévalence liée à l'âge : <span class=\"kw-chiffre\">2-4 % après 65 ans</span>, <span class=\"kw-chiffre\">15 % à 80 ans</span>. <strong>Facteurs de risque :</strong> <span class=\"kw-etio\">génétiques</span> (homozygotie pour l'allèle <span class=\"kw-bio\">ApoE ε4</span>) et <span class=\"kw-etio\">environnementaux</span> (FdR cérébro-vasculaires, faible niveau d'éducation).</p>\n      <p>Comme l'immense majorité des maladies <span class=\"kw-def\">neurodégénératives</span>, la <span class=\"kw-def\">maladie d'Alzheimer</span> est une <span class=\"kw-def\">protéinopathie</span> : accumulation d'agrégats de <span class=\"kw-bio\">protéines anormales</span> associée à une <span class=\"kw-alerte\">perte neuronale</span>. L'équation lésionnelle :</p>\n      <p><span class=\"kw-alerte\">Plaques amyloïdes + dégénérescence neurofibrillaire + perte neuronale → atrophie hippocampique</span>.</p>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 380\" role=\"img\" aria-label=\"Schéma des principales lésions de la maladie d'Alzheimer. Deux familles de lésions coexistent : à gauche les plaques amyloïdes, dépôts extra-neuronaux de peptide bêta-amyloïde 42 issu du clivage de la protéine APP ; à droite la dégénérescence neurofibrillaire, accumulation intra-neuronale de protéine TAU hyper-phosphorylée. Ces deux lésions activent la neuro-inflammation par astrogliose et microgliose réactionnelles, qui entraîne la perte neuronale, laquelle aboutit lorsqu'elle est massive à l'atrophie hippocampique visible à l'IRM.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"20\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">Lésions de la maladie d'Alzheimer (protéinopathie)</text>\n          <rect class=\"fb-red\" x=\"20\" y=\"36\" width=\"250\" height=\"78\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"145\" y=\"56\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Plaques amyloïdes (séniles)</text>\n          <text class=\"tx-red\" x=\"145\" y=\"74\" text-anchor=\"middle\" font-size=\"11\">dépôt EXTRA-neuronal · sphérique</text>\n          <text class=\"tx-red\" x=\"145\" y=\"90\" text-anchor=\"middle\" font-size=\"11\">peptide Aβ-42</text>\n          <text class=\"tx-red\" x=\"145\" y=\"106\" text-anchor=\"middle\" font-size=\"11\">(clivage de la protéine APP)</text>\n          <rect class=\"fb-amber\" x=\"290\" y=\"36\" width=\"250\" height=\"78\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"415\" y=\"56\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Dégénérescence neurofibrillaire</text>\n          <text class=\"tx-amber\" x=\"415\" y=\"74\" text-anchor=\"middle\" font-size=\"11\">accumulation INTRA-neuronale</text>\n          <text class=\"tx-amber\" x=\"415\" y=\"90\" text-anchor=\"middle\" font-size=\"11\">protéine TAU</text>\n          <text class=\"tx-amber\" x=\"415\" y=\"106\" text-anchor=\"middle\" font-size=\"11\">hyper-phosphorylée</text>\n          <line class=\"ln\" x1=\"145\" y1=\"114\" x2=\"145\" y2=\"134\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"415\" y1=\"114\" x2=\"415\" y2=\"134\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"145\" y1=\"134\" x2=\"415\" y2=\"134\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"280\" y1=\"134\" x2=\"280\" y2=\"150\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,156 275,148 285,148\"/>\n          <rect class=\"fb-purple\" x=\"130\" y=\"158\" width=\"300\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-purple\" x=\"280\" y=\"178\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Neuro-inflammation</text>\n          <text class=\"tx-purple\" x=\"280\" y=\"195\" text-anchor=\"middle\" font-size=\"11\">astrogliose + microgliose réactionnelles</text>\n          <line class=\"ln\" x1=\"280\" y1=\"204\" x2=\"280\" y2=\"222\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,228 275,220 285,220\"/>\n          <rect class=\"fb-red\" x=\"130\" y=\"230\" width=\"300\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"250\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Destruction et perte neuronale</text>\n          <text class=\"tx-red\" x=\"280\" y=\"267\" text-anchor=\"middle\" font-size=\"11\">(lorsqu'elle est massive)</text>\n          <line class=\"ln\" x1=\"280\" y1=\"276\" x2=\"280\" y2=\"294\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,300 275,292 285,292\"/>\n          <rect class=\"fb-grey\" x=\"130\" y=\"302\" width=\"300\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"324\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Atrophie hippocampique</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"341\" text-anchor=\"middle\" font-size=\"11\"><span class=\"kw-imagerie\">IRM</span> T1 3D · échelle de Scheltens</text>\n        </svg>\n        <figcaption>Équation lésionnelle de la MA : plaques amyloïdes (extra-neuronales) + DNF tau (intra-neuronale) → neuro-inflammation → perte neuronale → atrophie hippocampique.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Lésion</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Plaques amyloïdes (séniles)</span></td><td><strong>Nature :</strong> lésions sphériques <span class=\"kw-def\">extra-cellulaires</span> <br><strong>Composition :</strong> protéine <span class=\"kw-bio\">β-amyloïde</span> — peptide <span class=\"kw-bio\">Aβ-42</span>, issu du clivage de la protéine mère <span class=\"kw-bio\">APP</span> (Amyloid Precursor Protein) <br><strong>Topographie :</strong> cortex associatifs (préfrontaux, pariétaux, temporaux) ; <span class=\"kw-alerte\">épargne</span> le cortex visuel primaire et le cortex moteur</td></tr>\n          <tr><td><span class=\"kw-def\">Dégénérescence neurofibrillaire (DNF)</span></td><td><strong>Nature :</strong> protéine <span class=\"kw-bio\">TAU</span> anormalement <span class=\"kw-def\">hyper-phosphorylée</span>, s'accumulant en <span class=\"kw-def\">intra-neuronal</span> sous forme de filaments appariés en hélice <br><strong>Conséquence :</strong> <span class=\"kw-alerte\">perturbation du transport axonal</span> et dysfonctionnement synaptique <br><strong>Topographie :</strong> régions temporales internes — <span class=\"kw-clinique\">hippocampe</span>, <span class=\"kw-clinique\">cortex entorhinal</span></td></tr>\n        </tbody>\n      </table>\n      <p>L'accumulation de ces lésions active la <span class=\"kw-def\">neuroinflammation</span> par activation des cellules gliales — astrogliose et microgliose réactionnelles —, qui entraîne la <span class=\"kw-alerte\">destruction et la perte neuronale</span>. Lorsque celle-ci est massive, elle aboutit à l'<span class=\"kw-radio\">atrophie des régions affectées</span>, au premier rang desquelles l'<span class=\"kw-radio\">hippocampe</span> (visible à l'<span class=\"kw-imagerie\">IRM T1 3D</span>, cotée par l'<span class=\"kw-radio\">échelle de Scheltens</span>).</p>","frequence":0},{"id":"108-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques de la MA aux différentes phases","contenu":"<p>L'évolution de la <span class=\"kw-def\">maladie d'Alzheimer</span> se fait en <span class=\"kw-chiffre\">trois phases</span>, corrélées à la diffusion des lésions et au score <span class=\"kw-bio\">MMSE</span>.</p>\n      \n      <table >\n        <thead><tr><th>Phase</th><th>Tableau clinique</th></tr></thead>\n        <tbody>\n          <tr><td>Phase prodromale (pré-démentielle) — TNC mineur</td><td>Patient <span class=\"kw-clinique\">autonome</span> ; <span class=\"kw-clinique\">plainte mnésique</span> avec « oubli à mesure » (fait répéter) ; <span class=\"kw-clinique\">anosognosie</span> alors que la famille s'inquiète ; <span class=\"kw-clinique\">trouble de consolidation</span> en mémoire épisodique</td></tr>\n          <tr><td>Phase d'état (démence)</td><td><span class=\"kw-alerte\">Perte d'autonomie</span> pour les gestes de la vie quotidienne (téléphone, voiture, argent) ; aggravation du <span class=\"kw-clinique\">trouble de la mémoire</span> ; <span class=\"kw-clinique\">syndrome aphaso-apraxo-agnosique</span> : apraxie idéo-motrice + aphasie motrice (baisse de la fluence verbale sans trouble de la compréhension)</td></tr>\n          <tr><td>Phase de démence très sévère — TNC majeur</td><td>Survient <span class=\"kw-chiffre\">7-8 ans</span> après les premiers symptômes ; <span class=\"kw-alerte\">perte d'autonomie totale</span> ; non-reconnaissance des proches ; troubles du comportement (agitation, apathie, <span class=\"kw-clinique\">hallucinations visuelles</span>, déambulation) ; <span class=\"kw-alerte\">troubles de la déglutition</span> et dénutrition ; troubles sphinctériens ; troubles neurologiques (<span class=\"kw-clinique\">épilepsie</span>, <span class=\"kw-clinique\">myoclonies</span>) ; décès en état grabataire</td></tr>\n        </tbody>\n      </table>\n      <p>Le suivi de la sévérité s'appuie sur le MMSE : déclin <span class=\"kw-chiffre\">léger (MMSE &gt; 20)</span>, <span class=\"kw-chiffre\">modéré (10 &lt; MMSE)</span>, <span class=\"kw-chiffre\">sévère (MMSE &lt; 10)</span>, ou <span class=\"kw-alerte\">rapide</span> (perte ≥ 3 points par an).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":2},{"id":"108-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le profil des troubles de la mémoire de la MA","contenu":"<p>Le trouble mnésique de la <span class=\"kw-def\">maladie d'Alzheimer</span> a un profil très caractéristique : un <span class=\"kw-def\">trouble de la consolidation en mémoire épisodique</span>, c'est-à-dire une <span class=\"kw-alerte\">atteinte du stockage</span> de l'information. Il s'explore typiquement par le <span class=\"kw-clinique\">test des 5 mots</span>.</p>\n      <table >\n        <thead><tr><th>Étape du test</th><th>Résultat dans la MA</th></tr></thead>\n        <tbody>\n          <tr><td>Encodage (rappel immédiat)</td><td><span class=\"kw-clinique\">Absence de difficulté</span> : le patient rappelle les mots immédiatement</td></tr>\n          <tr><td>Rappel différé (après quelques minutes + épreuve intercurrente)</td><td><span class=\"kw-alerte\">Impossibilité de restituer</span> les mots</td></tr>\n          <tr><td>Rappel indicé</td><td><span class=\"kw-alerte\">Non amélioré par les indices</span> ; <span class=\"kw-clinique\">intrusions</span> (mots ne faisant pas partie de la liste)</td></tr>\n        </tbody>\n      </table>\n      <p>L'absence d'aide par l'indiçage permet de distinguer la MA d'un simple <span class=\"kw-clinique\">trouble de la récupération</span> : c'est la signature d'une <span class=\"kw-alerte\">atteinte du stockage</span>.</p>\n      <p>En consultation mémoire, le test neuropsychologique de référence est le <span class=\"kw-clinique\">Rappel libre / rappel indicé à 16 items (RL-RI 16)</span> : il confirme l'effondrement des capacités de rappel et le trouble de la consolidation (faiblesse de l'aide normalement pourvue par les indices de catégorie).</p>\n      <div class=\"callout callout-warn\"><strong>À distinguer — le « trouble pseudo-amnésique » :</strong> difficulté à restituer les 5 mots mais <span class=\"kw-clinique\">aidé par les indices</span> = altération de l'enregistrement / récupération <strong>sans</strong> atteinte de la consolidation. Évoque une <span class=\"kw-etio\">dépression</span>, un <span class=\"kw-etio\">trouble du sommeil</span> ou une <span class=\"kw-etio\">anxiété</span> — pas une MA.</div>","frequence":1},{"id":"108-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels de la MA","contenu":"<p>Devant un syndrome démentiel, plusieurs entités sont à distinguer de la <span class=\"kw-def\">maladie d'Alzheimer</span> — leur reconnaissance change la prise en charge et le pronostic.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Éléments distinctifs</th></tr></thead>\n        <tbody>\n          <tr><td>Maladie à corps de Lewy</td><td><span class=\"kw-clinique\">Fluctuations</span> ; <span class=\"kw-clinique\">hallucinations visuelles précoces</span> ; <span class=\"kw-clinique\">syndrome parkinsonien</span> akinéto-rigide ; troubles du comportement en sommeil paradoxal ; <span class=\"kw-alerte\">hypersensibilité aux neuroleptiques</span></td></tr>\n          <tr><td>Démence lobaire fronto-temporale (DLFT)</td><td><span class=\"kw-clinique\">Troubles comportementaux précoces</span> : désinhibition, perte des convenances sociales, apathie, perte d'empathie ; <span class=\"kw-clinique\">syndrome dysexécutif</span> ; <span class=\"kw-clinique\">aphasie</span> progressive ; survenue vers <span class=\"kw-chiffre\">50-60 ans</span></td></tr>\n          <tr><td>Démence vasculaire</td><td><span class=\"kw-def\">2ᵉ cause de démence</span> ; déclin <span class=\"kw-clinique\">brutal ou en « marche d'escalier »</span> ; séquelles focales ; <span class=\"kw-radio\">lacunes</span> et <span class=\"kw-radio\">hypersignaux de la substance blanche</span> à l'<span class=\"kw-imagerie\">IRM</span> <br><strong>Forme particulière — <span class=\"kw-def\">angiopathie amyloïde cérébrale</span> :</strong> <span class=\"kw-etio\">dépôts Aβ</span> dans les parois artérielles ; <span class=\"kw-alerte\">hémorragies corticales lobaires</span> + <span class=\"kw-radio\">microsaignements</span> (<span class=\"kw-imagerie\">IRM T2*</span>) ; associée à une démence dans <span class=\"kw-chiffre\">10-30 %</span> des cas</td></tr>\n          <tr><td>Paralysie supranucléaire progressive (PSP) — rang B</td><td><span class=\"kw-clinique\">Chutes précoces</span> ; <span class=\"kw-clinique\">syndrome parkinsonien axial dopa-résistant</span> ; paralysie de l'oculomotricité verticale (limitation des saccades) ; <span class=\"kw-radio\">IRM « signe du colibri »</span> = atrophie mésencéphalique</td></tr>\n          <tr><td>Dégénérescence cortico-basale (DCB) — rang B</td><td><span class=\"kw-clinique\">Apraxie gestuelle asymétrique</span> (« main inutile ») ; <span class=\"kw-clinique\">syndrome parkinsonien asymétrique</span> ; <span class=\"kw-radio\">atrophie pariétale très asymétrique</span></td></tr>\n          <tr><td>Hydrocéphalie chronique de l'adulte</td><td><span class=\"kw-clinique\">Triade d'Hakim et Adams</span> : troubles de la marche + troubles cognitifs + troubles vésico-sphinctériens — <span class=\"kw-alerte\">cause curable</span></td></tr>\n          <tr><td>Hématome sous-dural chronique</td><td><span class=\"kw-clinique\">Ralentissement psychomoteur</span>, apathie, syndrome frontal — <span class=\"kw-alerte\">cause curable</span> à éliminer systématiquement</td></tr>\n          <tr><td>« Démences » secondaires curables — rang A</td><td><span class=\"kw-etio\">Hypothyroïdie</span> ; carence en <span class=\"kw-bio\">vitamine B12 / folates</span> ; <span class=\"kw-etio\">syphilis</span> (neurosyphilis) ; <span class=\"kw-etio\">infection VIH</span> ; <span class=\"kw-etio\">méningiome frontal</span> — potentiellement <span class=\"kw-alerte\">réversibles</span>, à toujours rechercher</td></tr>\n          <tr><td>Démence rapidement progressive (&lt;<span class=\"kw-chiffre\"> 1 an</span>)</td><td><span class=\"kw-etio\">Maladie de Creutzfeldt-Jakob</span> (<span class=\"kw-clinique\">syndrome cérébelleux</span>, <span class=\"kw-clinique\">myoclonies</span>, décès en quelques mois) ; <span class=\"kw-etio\">encéphalite auto-immune</span> ou paranéoplasique — à évoquer devant tout syndrome démentiel d'installation &lt;<span class=\"kw-chiffre\"> 1 an</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé · 106 — Parkinson</em></p>","frequence":0},{"id":"108-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge non médicamenteuse de la MA, y compris l’aide des réseaux ville-hôpital","contenu":"<p>La prise en charge de la <span class=\"kw-def\">maladie d'Alzheimer</span> est avant tout <span class=\"kw-def\">non médicamenteuse</span> et repose sur une coordination ville-hôpital. Elle relève d'une <span class=\"kw-def\">ALD 15</span> (affection de longue durée).</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Moyens</th></tr></thead>\n        <tbody>\n          <tr><td>Stabilisation du TNC</td><td><span class=\"kw-clinique\">Rééducation (remédiation) cognitive</span> avec orthophoniste ; <span class=\"kw-clinique\">réhabilitation cognitive</span> pour maintenir ou restaurer l'autonomie ; <span class=\"kw-clinique\">stimulation cognitive</span></td></tr>\n          <tr><td>Réseaux ville-hôpital</td><td><span class=\"kw-ttt\">Équipe spécialisée Alzheimer (ESA)</span> à domicile, pour les formes légères à modérées ; <span class=\"kw-ttt\">centre d'accueil de jour</span> pour la stimulation cognitive ; <span class=\"kw-ttt\">MAIA</span> en cas de perte d'autonomie ou de cas complexe (sujet seul, refus de soins)</td></tr>\n          <tr><td>Aides humaines</td><td>Aide à domicile ; soutien logistique des aidants</td></tr>\n          <tr><td>Aides financières</td><td>Prise en charge à <span class=\"kw-chiffre\">100 %</span> au titre de l'<span class=\"kw-def\">ALD 15</span> ; <span class=\"kw-ttt\">APA</span> (allocation personnalisée d'autonomie, selon grille <span class=\"kw-bio\">AGGIR</span> si <span class=\"kw-chiffre\">&gt; 60 ans</span>) ; <span class=\"kw-ttt\">PCH</span> (prestation de compensation du handicap) si <span class=\"kw-chiffre\">&lt; 60 ans</span></td></tr>\n          <tr><td>Protection juridique</td><td>Mesures médico-légales selon le degré de perte d'autonomie : <span class=\"kw-ttt\">sauvegarde de justice</span> ; <span class=\"kw-ttt\">tutelle</span> ; <span class=\"kw-ttt\">habilitation familiale</span></td></tr>\n          <tr><td>Institutionnalisation</td><td>Si le maintien au domicile devient impossible : maison de retraite médicalisée (EHPAD) ; service de long séjour</td></tr>\n          <tr><td>Aide aux aidants</td><td><span class=\"kw-clinique\">Information</span>, soutien et accompagnement des proches ; <span class=\"kw-ttt\">plateformes d'accompagnement et de répit</span> ; <span class=\"kw-ttt\">associations de familles</span> ; prévention de l'épuisement de l'aidant</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Les <strong>mesures non médicamenteuses priment</strong> : le traitement médicamenteux (inhibiteurs de la cholinestérase, anti-glutamate) n'a qu'une place d'appoint et ne modifie pas l'organisation des soins.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 132 — Troubles cognitifs du sujet âgé</em></p>","frequence":1},{"id":"108-12","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Préciser les principes du raisonnement topographique devant un syndrome démentiel","contenu":"<p>Le raisonnement topographique devant un syndrome démentiel relie chaque <span class=\"kw-def\">grande fonction cognitive</span> à un <span class=\"kw-def\">territoire cérébral</span> : l'atteinte d'un territoire produit un syndrome clinique caractéristique, exploré par des tests ciblés.</p>\n      <p><strong>Préalable :</strong> l'<span class=\"kw-clinique\">attention</span> doit <span class=\"kw-alerte\">toujours être vérifiée avant</span> d'explorer ou d'interpréter un trouble neurocognitif — son atteinte (système d'éveil cortical) désorganise globalement la pensée et réalise l'<span class=\"kw-def\">état confusionnel</span>.</p>\n      <table >\n        <thead><tr><th>Fonction</th><th>Topographie</th><th>Syndrome en cas d'atteinte</th></tr></thead>\n        <tbody>\n          <tr><td>Intégrations perceptives</td><td>Lobes temporaux et lobes pariétaux</td><td>Lobe temporal : <span class=\"kw-clinique\">aphasie</span>, agnosie visuelle <br>Lobe pariétal : apraxie, négligence, trouble du schéma corporel → <span class=\"kw-def\">syndrome aphaso-apraxo-agnosique</span></td></tr>\n          <tr><td>Mémoire</td><td>Partie interne des <span class=\"kw-clinique\">lobes temporaux</span> : cortex adjacents et <span class=\"kw-clinique\">hippocampe</span></td><td><span class=\"kw-clinique\">Amnésie avec « oubli à mesure »</span> — profil de la maladie d'Alzheimer</td></tr>\n          <tr><td>Fonctions exécutives</td><td>Lobes frontaux et préfrontaux ; <span class=\"kw-clinique\">ganglions de la base</span></td><td><span class=\"kw-def\">Syndrome frontal</span> : défaut d'initiation, apathie, comportements automatiques, perte d'empathie</td></tr>\n        </tbody>\n      </table>\n      <p>Chaque territoire dispose de <span class=\"kw-clinique\">tests dédiés</span> : compréhension d'ordres simples (temporal), copie de figure et test de l'horloge (pariétal), <span class=\"kw-clinique\">épreuve des 5 mots</span> (mémoire), <span class=\"kw-bio\">batterie rapide d'efficience frontale (BREF)</span> pour le frontal.</p>","frequence":2},{"id":"108-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et les objectifs d’imagerie devant une démence ou une confusion","contenu":"<p>Devant une démence comme devant une <span class=\"kw-clinique\">confusion</span>, l'imagerie cérébrale a un <span class=\"kw-def\">double objectif</span> : éliminer une <span class=\"kw-alerte\">cause curable</span> et orienter l'étiologie.</p>\n      <table >\n        <thead><tr><th>Objectif</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>Arguments négatifs (éliminer)</td><td>Éliminer un <span class=\"kw-etio\">processus expansif intracrânien</span> ; une <span class=\"kw-etio\">hydrocéphalie</span> ; détecter des <span class=\"kw-etio\">lésions ischémiques ou hémorragiques</span></td></tr>\n          <tr><td>Arguments positifs (orienter)</td><td><span class=\"kw-radio\">Atrophie hippocampique</span> (maladie d'Alzheimer), cotée par l'<span class=\"kw-radio\">échelle de Scheltens</span> de 0 (pas d'atrophie) à 4 (atrophie sévère)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Modalités dans la démence</strong> — l'imagerie est <span class=\"kw-def\">systématique</span> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">IRM encéphalique</span> = examen de référence : séquences <span class=\"kw-imagerie\">T1 3D hippocampique</span>, T2, FLAIR, T2* (écho de gradient), diffusion si évolution rapide.</li>\n        <li><span class=\"kw-imagerie\">TDM cérébrale</span> en alternative si l'<span class=\"kw-imagerie\">IRM</span> est <span class=\"kw-ci\">contre-indiquée</span>.</li>\n        <li><span class=\"kw-imagerie\">DAT-scan</span> si suspicion de démence à corps de Lewy ; <span class=\"kw-imagerie\">TEP</span> ou TEMP dans les cas difficiles.</li>\n      </ul>\n      <p><strong>Dans la confusion</strong>, la <span class=\"kw-imagerie\">TDM cérébrale</span> non injectée n'est <span class=\"kw-alerte\">pas systématique</span> : elle est indiquée en 1ʳᵉ intention devant un <span class=\"kw-clinique\">signe de localisation</span>, une suspicion d'<span class=\"kw-etio\">HSA</span>, un <span class=\"kw-clinique\">traumatisme crânien</span>, une <span class=\"kw-clinique\">chute</span> peu claire ou un patient sous <span class=\"kw-ttt\">anticoagulant</span>.</p>","frequence":1},{"id":"108-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie en imagerie de l’hématome sous-dural (HSD) chronique","contenu":"<p>L'<span class=\"kw-def\">hématome sous-dural (HSD) chronique</span> est une cause <span class=\"kw-alerte\">curable</span> de syndrome démentiel ou confusionnel, à toujours éliminer chez le sujet âgé.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Nature</td><td><span class=\"kw-def\">Collection extra-parenchymateuse</span> liquidienne, située dans les espaces méningés, entre <span class=\"kw-def\">dure-mère et arachnoïde</span></td></tr>\n          <tr><td>Aspect en imagerie</td><td><span class=\"kw-radio\">Mélange hypodense et hyperdense</span> réalisant un aspect <span class=\"kw-radio\">« en croissant »</span> ; <span class=\"kw-radio\">souvent bilatéral</span></td></tr>\n          <tr><td>Facteurs favorisants</td><td><span class=\"kw-etio\">Déshydratation</span> ; <span class=\"kw-etio\">alcoolisme chronique</span> ; <span class=\"kw-ttt\">traitement anticoagulant</span></td></tr>\n          <tr><td>Clinique</td><td>Troubles cognitifs : <span class=\"kw-clinique\">ralentissement psychomoteur</span> ; <span class=\"kw-clinique\">apathie</span> ; <span class=\"kw-clinique\">syndrome frontal</span> ; <span class=\"kw-clinique\">confusion</span></td></tr>\n          <tr><td>Traitement</td><td><span class=\"kw-clinique\">Surveillance simple</span> ± <span class=\"kw-clinique\">évacuation chirurgicale</span> à discuter</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Devant un <span class=\"kw-def\">syndrome confusionnel</span> ou démentiel chez un sujet âgé sous <span class=\"kw-ttt\">anticoagulant</span> ou éthylique, l'HSD chronique doit être systématiquement évoqué — y compris en l'absence de traumatisme rapporté.</div>","frequence":0},{"id":"108-15","rang":"A","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d’un HSD chronique","contenu":"<p>Objectif officiel <span class=\"kw-def\">rang A « Contenu multimédia »</span> : savoir reconnaître une <span class=\"kw-def\">TDM cérébrale d'hématome sous-dural chronique</span> et énoncer les éléments sémiologiques caractéristiques. Checklist de lecture systématique :</p>\n      <table >\n        <thead><tr><th>Critère sémiologique</th><th>Description radiologique</th></tr></thead>\n        <tbody>\n          <tr><td>Localisation</td><td><span class=\"kw-radio\">Collection extra-axiale</span> (extra-parenchymateuse), située dans l'espace sous-dural — entre <span class=\"kw-def\">dure-mère</span> et <span class=\"kw-def\">arachnoïde</span></td></tr>\n          <tr><td>Forme</td><td>Aspect <span class=\"kw-radio\">« en croissant »</span> (concave vers le parenchyme) — à différencier de l'<span class=\"kw-etio\">hématome extra-dural</span> qui est <span class=\"kw-radio\">biconvexe en lentille</span></td></tr>\n          <tr><td>Densité</td><td><span class=\"kw-radio\">Hypodense (10-30 UH)</span> à la phase chronique — possible <span class=\"kw-radio\">aspect mixte hypo/hyperdense</span> en cas de resaignement (« HSD aigu sur chronique ») avec <span class=\"kw-radio\">niveau liquide-liquide</span></td></tr>\n          <tr><td>Extension</td><td><span class=\"kw-radio\">Traverse les sutures crâniennes</span> (à la différence de l'<span class=\"kw-etio\">hématome extra-dural</span> qui s'arrête aux sutures) ; <span class=\"kw-radio\">souvent bilatéral</span> chez le sujet âgé</td></tr>\n          <tr><td>Effet de masse</td><td><span class=\"kw-alerte\">Effacement des sillons corticaux</span> en regard ; <span class=\"kw-alerte\">compression du ventricule latéral</span> homolatéral ; <span class=\"kw-alerte\">déviation de la ligne médiane</span> à mesurer (engagement sous-falcoriel si &gt; <span class=\"kw-chiffre\">5 mm</span>)</td></tr>\n          <tr><td>Signes associés</td><td><span class=\"kw-radio\">Atrophie cortico-sous-corticale</span> sous-jacente (terrain âgé) ; rechercher une <span class=\"kw-radio\">cloison de fibrine</span> intra-collection (HSD multi-cloisonné, plus difficile à drainer)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/108/tdm-hsd-chronique.png\" alt=\"TDM cérébrale sans injection, coupes axiales — deux patients : HSD gauche chronique en croissant hypodense avec effet de masse ; HSD bilatéral chronique avec resaignement (zones hypodenses et hyperdenses) et déviation de la ligne médiane\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM cérébrale</span> sans injection, coupes axiales (deux patients distincts). <strong>À gauche :</strong> <span class=\"kw-def\">HSD gauche chronique</span> — collection péricérébrale en <span class=\"kw-radio\">croissant</span>, <span class=\"kw-radio\">hypodense</span>, dépassant les sutures, avec effacement du ventricule latéral et <span class=\"kw-alerte\">effet de masse</span> (engagement sous-falcoriel débutant). <strong>À droite :</strong> <span class=\"kw-def\">HSD bilatéral chronique avec resaignement</span> — zones hypodenses (hématome chronique) et hyperdenses (saignement aigu), <span class=\"kw-alerte\">déviation de la ligne médiane</span>. Source : fiche source EDN — banque imagerie « Imagerie à connaître » (items 108/132).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\"><strong>Piège classique :</strong> chez le sujet âgé sous <span class=\"kw-ttt\">anticoagulant</span> ou <span class=\"kw-etio\">éthylique chronique</span>, l'HSD chronique peut survenir <span class=\"kw-alerte\">sans traumatisme rapporté</span> — la <span class=\"kw-imagerie\">TDM</span> doit être demandée systématiquement devant toute <span class=\"kw-clinique\">confusion</span> ou <span class=\"kw-clinique\">syndrome frontal</span> d'apparition récente.</div>","frequence":0},{"id":"108-16","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie en imagerie de l’hydrocéphalie chronique de l’adulte","contenu":"<p>L'<span class=\"kw-def\">hydrocéphalie chronique de l'adulte</span> est une <span class=\"kw-alerte\">cause curable</span> de détérioration cognitive, à reconnaître devant la <span class=\"kw-def\">triade d'Hakim et Adams</span>.</p>\n      <table >\n        <thead><tr><th>Versant</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Triade clinique d'Hakim et Adams</td><td><strong>Marche :</strong> <span class=\"kw-clinique\">apraxie de la marche</span> ; <span class=\"kw-clinique\">astasie-abasie</span> ; marche précautionneuse à <span class=\"kw-clinique\">petits pas</span> ; élargissement du polygone de sustentation ; <span class=\"kw-clinique\">rétropulsion</span> <br><strong>Cognition :</strong> <span class=\"kw-clinique\">syndrome sous-cortico-frontal</span> — ralentissement idéatoire, déficit attentionnel, syndrome dysexécutif <br><strong>Sphincters :</strong> <span class=\"kw-clinique\">troubles vésico-sphinctériens</span></td></tr>\n          <tr><td>Sémiologie en imagerie (<span class=\"kw-imagerie\">IRM</span>)</td><td><span class=\"kw-radio\">Dilatation tétra-ventriculaire sans effet de masse</span> ; sillons corticaux plus ou moins effacés ; résorption trans-épendymaire (suffusion de liquide péri-ventriculaire) — hypodensité au <span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-radio\">hypersignal T2 / FLAIR</span> de la substance blanche péri-ventriculaire</td></tr>\n          <tr><td>Traitement</td><td><span class=\"kw-clinique\">Ponction lombaire évacuatrice</span> (<span class=\"kw-chiffre\">30 mL</span> de <span class=\"kw-bio\">LCR</span> par jour pendant <span class=\"kw-chiffre\">3 jours</span>) ± <span class=\"kw-clinique\">dérivation ventriculo-péritonéale (DVP)</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"108-17","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens de médecine nucléaire dans les démences","contenu":"<p>Les examens de <span class=\"kw-def\">médecine nucléaire</span> ne sont <span class=\"kw-alerte\">pas systématiques</span> : ils sont réservés aux <span class=\"kw-def\">formes de diagnostic difficile</span> — <span class=\"kw-clinique\">forme débutante</span>, <span class=\"kw-clinique\">TNC mineur</span>, <span class=\"kw-clinique\">présentation atypique</span>, <span class=\"kw-clinique\">démence à début précoce</span> (&lt;<span class=\"kw-chiffre\"> 65 ans</span>).</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Principe et résultats</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">Scintigraphie de perfusion (TEMP)</span></td><td><strong>Principe :</strong> traceur de perfusion cérébrale (<span class=\"kw-bio\">HMPAO</span>-<span class=\"kw-bio\">⁹⁹ᵐTc</span>) <br><strong>MA :</strong> hypoperfusion des régions corticales associatives et temporales internes (<span class=\"kw-etio\">maladie d'Alzheimer</span>) <br><strong>DLFT :</strong> <span class=\"kw-radio\">hypoperfusion frontale et temporale antérieure</span> (<span class=\"kw-etio\">démence lobaire fronto-temporale</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TEP-TDM au ¹⁸F-FDG</span></td><td><strong>Principe :</strong> tomographie par émission de positons au <span class=\"kw-bio\">¹⁸F-FDG</span> — mesure du métabolisme glucidique cérébral <br><strong>Résultat :</strong> <span class=\"kw-radio\">hypométabolisme cortical postérieur</span> (pariéto-temporal, cingulaire postérieur) — argument positif d'imagerie métabolique en faveur de la <span class=\"kw-etio\">MA</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">DAT-scan (TEMP à l'ioflupane)</span></td><td><strong>Principe :</strong> traceur (<span class=\"kw-bio\">¹²³I-ioflupane</span>) fixant le <span class=\"kw-def\">transporteur présynaptique de la dopamine (DAT)</span> dans le striatum <br><strong>Résultat :</strong> <span class=\"kw-radio\">hypofixation striatale précoce</span>, débutant à la <span class=\"kw-radio\">partie postérieure du putamen</span> <br><strong>Indication :</strong> suspicion de <span class=\"kw-etio\">maladie à corps de Lewy</span> ou d'<span class=\"kw-etio\">atrophie multi-systématisée</span>, uniquement si syndrome parkinsonien non typique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan biologique plasmatique (HAS 2011)</strong> — argument <span class=\"kw-def\">négatif</span> servant à éliminer les <span class=\"kw-def\">démences secondaires curables</span> :</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Bilan minimal</td><td><span class=\"kw-bio\">NFS-plaquettes</span> ; <span class=\"kw-bio\">VS</span> ; <span class=\"kw-bio\">ionogramme</span> ; <span class=\"kw-bio\">calcémie</span> ; albuminémie ; créatininémie + <span class=\"kw-bio\">clairance</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">TSHus</span> ; <span class=\"kw-bio\">glycémie</span> à jeun</td></tr>\n          <tr><td>Selon le contexte</td><td>Bilan hépatique (transaminases, γGT) et <span class=\"kw-bio\">vitamine B12 / folates</span> (en pratique quasi systématiques) ; <span class=\"kw-bio\">sérologies syphilis / Lyme / VIH</span> (cas particuliers)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Certitude vs probabilité :</strong> du vivant, le diagnostic de MA est un <span class=\"kw-def\">diagnostic de probabilité</span> (faisceau d'arguments positifs + négatifs) ; la <span class=\"kw-alerte\">certitude est neuropathologique</span> (post-mortem). Le <span class=\"kw-def\">diagnostic génétique</span> n'apporte une certitude que dans les rares formes <span class=\"kw-chiffre\">monogéniques</span> (&lt; <span class=\"kw-chiffre\">1 %</span>, transmission autosomique dominante) — à n'évoquer que si <span class=\"kw-clinique\">début &lt; 60 ans</span> + ATCD de démence du sujet jeune sur <span class=\"kw-chiffre\">≥ 2 g</span>énérations.</div>\n      <div class=\"callout callout-info\"><strong>Hiérarchie diagnostique :</strong> <span class=\"kw-imagerie\">IRM encéphalique</span> + biologie standard suffisent à un diagnostic de <span class=\"kw-def\">haute probabilité</span>. L'<span class=\"kw-imagerie\">imagerie métabolique</span> et les biomarqueurs du <span class=\"kw-bio\">LCS</span> (<span class=\"kw-bio\">Aβ-42</span> ↓, <span class=\"kw-bio\">TAU</span> ↑, <span class=\"kw-bio\">phospho-TAU</span> ↑) ne sont sollicités qu'en <span class=\"kw-def\">seconde ligne</span>, dans les cas difficiles.</div>","frequence":0}],"astuces":[{"type":"danger","titre":"Démence à corps de Lewy : neuroleptiques classiques INTERDITS","contenu":"Devant troubles cognitifs fluctuants + hallucinations visuelles + parkinsonisme + RBD, penser DCL. L'halopéridol et les neuroleptiques classiques provoquent une aggravation parkinsonienne sévère, parfois un syndrome malin. Préférer quétiapine ou clozapine à très faible dose. Confirmer par DAT-scan."},{"type":"warn","titre":"Toute confusion peut révéler une démence sous-jacente","contenu":"30 à 50 % des patients ayant fait un épisode confusionnel présentent un déclin cognitif persistant. Évaluation cognitive à distance (MMSE/MoCA à 3-6 mois) systématique — surtout chez le sujet âgé."},{"type":"tip","titre":"Profil hippocampique = signature Alzheimer","contenu":"RL/RI-16 de Grober et Buschke : rappel libre effondré + non corrigé par l'indiçage sémantique + reconnaissance altérée avec intrusions = atteinte hippocampique = MA. Si l'indiçage corrige → profil sous-cortico-frontal (vasculaire, parkinsonien, dépression)."},{"type":"danger","titre":"Anticholinestérasiques et mémantine : NON remboursés","contenu":"Depuis 2018, la HAS a déremboursé les anticholinestérasiques (donépézil, rivastigmine, galantamine) et la mémantine pour SMR insuffisant. La PEC de la MA est donc essentiellement non médicamenteuse : stimulation cognitive, ergothérapie, soutien aidants, ALD 15."},{"type":"info","titre":"Triade de Hakim-Adams = hydrocéphalie chronique = CURABLE","contenu":"Marche à petits pas magnétique + troubles cognitifs sous-cortico-frontaux + incontinence urinaire chez un sujet âgé. IRM : dilatation tétraventriculaire disproportionnée + Evans > 0,3 + signe DESH. Tap-test puis dérivation ventriculo-péritonéale → réversibilité possible."},{"type":"warn","titre":"HSD chronique : densité variable selon l'âge","contenu":"Aigu = hyperdense, subaigu (3 j - 3 sem) = ISO-dense (piège !), chronique > 3 sem = hypodense. Si bilatéral et symétrique en phase subaiguë, l'HSD peut être invisible : rechercher effacement bilatéral des sillons et ventricules « pincés »."}],"strategie":{"urgence":"<p><strong>Degré :</strong> le <span class=\"kw-def\">syndrome confusionnel</span> est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique</span> imposant l’<span class=\"kw-ttt\">hospitalisation</span>.<br><strong>1ᵉʳ geste :</strong> évaluer le retentissement à court terme (<span class=\"kw-clinique\">constantes vitales</span>) et traiter sans délai les <span class=\"kw-alerte\">troubles vitaux</span> (ex. <span class=\"kw-alerte\">état de choc</span>).<br><strong>Priorité :</strong> le <span class=\"kw-ttt\">traitement étiologique</span> — seul le traitement de la cause permet la guérison ; chez le sujet âgé = correction des <span class=\"kw-def\">facteurs précipitants</span>.<br><strong>Pronostic :</strong> mauvais — risque de mortalité <span class=\"kw-chiffre\">×6 à 6 mois</span> en gériatrie.</p>","hospit":"<p><strong>Hospitalisation :</strong> la règle (urgence diagnostique et thérapeutique).<br><strong>Orientation :</strong> filière gériatrique — <span class=\"kw-def\">structure</span> ou <span class=\"kw-def\">expertise gériatrique</span> ; anticiper le parcours de soins quand un <span class=\"kw-def\">facteur précipitant</span> est programmé (<span class=\"kw-etio\">chirurgie</span>, <span class=\"kw-etio\">anesthésie</span>).<br><strong>Réanimation / soins intensifs :</strong> si <span class=\"kw-alerte\">troubles vitaux</span> ou défaillance d’organe.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Trouble de la vigilance</span> / <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">état de choc</span> ou <span class=\"kw-alerte\">détresse respiratoire</span></li><li><span class=\"kw-clinique\">Fièvre</span> + confusion sans point d’appel → <span class=\"kw-etio\">méningite</span> / <span class=\"kw-etio\">méningo-encéphalite</span> (<span class=\"kw-bio\">ponction lombaire</span>)</li><li><span class=\"kw-clinique\">Signe de localisation neurologique</span> ou suspicion d’<span class=\"kw-etio\">hémorragie méningée</span> → <span class=\"kw-imagerie\">TDM cérébrale</span></li><li><span class=\"kw-etio\">Traumatisme crânien</span> même mineur, <span class=\"kw-etio\">chute</span> de circonstances peu claires → <span class=\"kw-imagerie\">TDM cérébrale</span></li><li><span class=\"kw-clinique\">Syndrome méningé</span> ou <span class=\"kw-alerte\">purpura</span></li><li>Cause métabolique immédiatement réversible : <span class=\"kw-etio\">hypoglycémie</span>, <span class=\"kw-etio\">hyponatrémie</span>, <span class=\"kw-etio\">hypercalcémie</span>, <span class=\"kw-etio\">hypoxie</span></li></ul>","principes":"<p><strong>Règle d’or :</strong> le <span class=\"kw-ttt\">traitement étiologique</span> est la priorité ; le recours médicamenteux est <span class=\"kw-clinique\">rare</span>, réservé à l’échec des mesures non médicamenteuses ; <span class=\"kw-ci\">éviter la contention</span>.</p><p><strong>Traitement étiologique <span class=\"q\">— priorité absolue</span></strong></p><p>seul le traitement de la cause permet la guérison</p><ul><li>Corriger les <span class=\"kw-def\">facteurs précipitants</span> : <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-etio\">globe vésical</span>, <span class=\"kw-clinique\">douleur</span>, <span class=\"kw-etio\">déshydratation</span></li><li>Iatrogénie : supprimer les <span class=\"kw-ttt\">traitements non indispensables</span> (psychotropes, <span class=\"kw-ci\">sans sevrage brutal</span>), diminuer les <span class=\"kw-ttt\">corticoïdes</span></li></ul><p><strong>Mesures non médicamenteuses <span class=\"q\">— à privilégier systématiquement</span></strong></p><ul><li>Environnement <span class=\"kw-clinique\">calme</span>, sécurisant, suffisamment éclairé (chambre individuelle)</li><li>Restaurer les <span class=\"kw-clinique\">repères temporo-spatiaux</span> (horloge, calendrier, rappels réguliers)</li><li>Lutter contre l’isolement sensoriel : <span class=\"kw-ttt\">prothèses auditives</span>, <span class=\"kw-ttt\">lunettes</span></li><li>Maintenir <span class=\"kw-ttt\">hydratation</span> / <span class=\"kw-ttt\">nutrition</span>, favoriser l’élimination, préserver la mobilité</li></ul><p><strong>Traitement médicamenteux <span class=\"q\">— rare, per os, faible dose, en cas d’échec</span></strong></p><ul><li><span class=\"kw-clinique\">Anxiété majeure</span> → <span class=\"kw-ttt\">BZD à demi-vie courte</span> (<span class=\"kw-ttt\">oxazépam</span>, <span class=\"kw-ttt\">alprazolam</span>) ; <span class=\"kw-ci\">éviter hydroxyzine, cyamémazine, halopéridol</span> (anticholinergiques)</li><li><span class=\"kw-clinique\">Délire</span> / <span class=\"kw-clinique\">hallucinations</span> compromettant la sécurité → <span class=\"kw-ttt\">neuroleptique atypique</span> (<span class=\"kw-ttt\">rispéridone</span>, <span class=\"kw-ttt\">olanzapine</span>) ; éviter les formes injectables (sinon <span class=\"kw-ttt\">tiapride IM</span>)</li><li>Terrain <span class=\"kw-def\">démence à corps de Lewy</span> / <span class=\"kw-def\">maladie de Parkinson</span> : <span class=\"kw-ci\">neuroleptiques habituels contre-indiqués</span> → <span class=\"kw-ttt\">clozapine</span></li></ul><p><strong>Contention physique <span class=\"q\">— dernier recours</span></strong></p><ul><li>Seulement après <span class=\"kw-clinique\">échec de toutes les mesures</span> précédentes</li><li>Sur <span class=\"kw-ttt\">prescription médicale</span> (responsabilité du prescripteur), <span class=\"kw-chiffre\">durée limitée</span>, réévaluée pluriquotidiennement</li><li><span class=\"kw-ci\">Aggrave le syndrome confusionnel</span> et l’agitation</li></ul>","suivi":"<p><strong>Réévaluation continue :</strong> rechercher systématiquement <span class=\"kw-clinique\">douleur</span>, <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-etio\">rétention aiguë d’urine</span> ; limiter les <span class=\"kw-ttt\">dispositifs invasifs</span> (cathéter, sonde urinaire, perfusion).<br><strong>Évolution :</strong> la <span class=\"kw-def\">confusion</span> peut régresser <span class=\"kw-clinique\">lentement</span> même après résolution de la cause — patience avant de juger l’efficacité.<br><strong>À distance :</strong> réévaluer l’<span class=\"kw-clinique\">état cognitif</span> à <span class=\"kw-chiffre\">6 mois</span> (peut révéler un <span class=\"kw-def\">syndrome démentiel débutant</span>).<br><strong>Contention (si posée) :</strong> <span class=\"kw-chiffre\">durée limitée</span>, réévaluation pluriquotidienne, surveillance spécifique.</p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/confusion-troubles-cognitifs-et-demence","label":"Collège CEN — Confusion, troubles cognitifs et démence"},{"href":"https://www.cen-neurologie.fr/premier-cycle/semiologie-analytique/syndrome-confusionnel","label":"Collège CEN — Syndrome confusionnel (sémiologie)"},{"href":"https://guide.hpci.ch/depistage-de-letat-confusionnel-aigu-outil-cam-confusion-assessment-method/","label":"HPCI — Outil CAM (Confusion Assessment Method)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Sujet âgé confus avec agitation — quel geste ? — Approche par étapes : 1) traitement étiologique · 2) mesures non médicamenteuses · 3) médicament seulement si échec","detail":"<h4>CAT — agitation du sujet âgé confus — Approche par étapes (collège de gériatrie)</h4>","branches":[{"to":"t-etio","label":"Cause somatique réversible (douleur, fécalome, globe vésical, iatrogénie)","color":"green"},{"to":"q-mesures","label":"Pas de cause corrigible / persistance malgré l’étiologie","color":"amber"}]},{"id":"t-etio","kind":"terminal","label":"Traitement étiologique en priorité","color":"green","detail":"<h4>Conduite</h4><ul><li>Corriger la ou les <span class=\"kw-def\">causes</span> : c’est souvent le <span class=\"kw-ttt\">seul traitement</span> nécessaire à la guérison.</li></ul><h4>Causes à traquer</h4><ul><li><span class=\"kw-clinique\">Douleur</span> non soulagée, <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-etio\">globe vésical</span> / rétention aiguë d’urine</li><li><span class=\"kw-etio\">Déshydratation</span>, troubles métaboliques, infection</li></ul><h4>Iatrogénie</h4><ul><li>Supprimer les <span class=\"kw-ttt\">traitements non indispensables</span> (psychotropes, <span class=\"kw-ci\">sans sevrage brutal</span>)</li><li>Diminuer les <span class=\"kw-ttt\">corticoïdes</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">NFS, CRP, ionogramme, calcémie, glycémie, créatininémie, BU</span>, <span class=\"kw-bio\">ECG</span> ± <span class=\"kw-imagerie\">TDM cérébrale</span> / <span class=\"kw-bio\">PL</span> / <span class=\"kw-bio\">EEG</span> selon le contexte</li></ul>"},{"id":"q-mesures","kind":"decision","label":"Agitation contrôlée par les mesures non médicamenteuses ? — Environnement calme et éclairé, repères temporo-spatiaux, prothèses auditives/lunettes, présence des proches, éviter la contention","branches":[{"to":"t-mesures","label":"Oui — agitation contrôlée","color":"green"},{"to":"q-type","label":"Non — auto/hétéro-agressivité ou soins impossibles","color":"amber"}]},{"id":"t-mesures","kind":"terminal","label":"Mesures non médicamenteuses suffisantes","color":"green","detail":"<h4>Mesures</h4><ul><li>Environnement <span class=\"kw-clinique\">calme</span>, sécurisant, éclairé (chambre individuelle)</li><li><span class=\"kw-clinique\">Repères temporo-spatiaux</span> : horloge, calendrier, rappels réguliers</li></ul><h4>Sensoriel & social</h4><ul><li><span class=\"kw-ttt\">Prothèses auditives</span>, <span class=\"kw-ttt\">lunettes</span> ; limiter les visites aux référents</li><li>Maintenir <span class=\"kw-ttt\">hydratation</span> / <span class=\"kw-ttt\">nutrition</span>, mobilité, élimination</li></ul><h4>À éviter</h4><ul><li><span class=\"kw-ci\">Contention physique</span> (aggrave l’agitation et la confusion)</li></ul>"},{"id":"q-type","kind":"decision","label":"Type de manifestation prédominante ? — Le médicament n’est justifié qu’en cas d’échec, par voie orale, à faible dose","branches":[{"to":"t-bzd","label":"Anxiété majeure","color":"amber"},{"to":"q-lewy","label":"Délire / hallucinations menaçant la sécurité","color":"amber"}]},{"id":"t-bzd","kind":"terminal","label":"BZD à demi-vie courte","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Anxiété majeure</span> uniquement (pas de traitement si l’anxiété n’est pas majeure)</li></ul><h4>Molécule</h4><ul><li><span class=\"kw-ttt\">Oxazépam 10 mg</span> ou <span class=\"kw-ttt\">alprazolam 0,25 mg</span> <span class=\"kw-ttt\">per os</span>, faible dose, à renouveler selon la réponse</li></ul><h4>À éviter</h4><ul><li><span class=\"kw-ci\">Hydroxyzine, cyamémazine, halopéridol</span> (composante anticholinergique)</li></ul>"},{"id":"q-lewy","kind":"decision","label":"Terrain démence à corps de Lewy ou maladie de Parkinson ?","branches":[{"to":"t-nl","label":"Non","color":"amber"},{"to":"t-lewy","label":"Oui (Lewy / Parkinson)","color":"red"}]},{"id":"t-nl","kind":"terminal","label":"Neuroleptique atypique à faible dose","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Délire</span> / <span class=\"kw-clinique\">hallucinations</span> à l’origine d’une agitation compromettant la sécurité (tout délire ne justifie pas un traitement)</li></ul><h4>Molécule</h4><ul><li><span class=\"kw-ttt\">Rispéridone 0,5 mg</span> (solution buvable) ou <span class=\"kw-ttt\">olanzapine</span> orodispersible, <span class=\"kw-ttt\">per os</span>, faible dose</li></ul><h4>Injectable</h4><ul><li>À éviter ; sinon <span class=\"kw-ttt\">tiapride IM 50 mg</span> (NL classique le moins anticholinergique)</li></ul><h4>Surveillance</h4><ul><li>Rechercher <span class=\"kw-clinique\">douleur</span> / <span class=\"kw-etio\">fécalome</span> / <span class=\"kw-etio\">rétention aiguë d’urine</span>, limiter les <span class=\"kw-ttt\">dispositifs invasifs</span> ; <span class=\"kw-ci\">contention</span> = dernier recours</li></ul>"},{"id":"t-lewy","kind":"terminal","label":"Quétiapine ou clozapine","color":"red","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-def\">Démence à corps de Lewy</span> ou <span class=\"kw-def\">maladie de Parkinson</span> : <span class=\"kw-ci\">neuroleptiques habituels contre-indiqués</span> (aggravation parkinsonienne)</li></ul><h4>Molécule</h4><ul><li>Privilégier <span class=\"kw-ttt\">quétiapine</span> ou <span class=\"kw-ttt\">clozapine</span>, faible dose</li></ul><h4>Surveillance</h4><ul><li>Réévaluation continue ; <span class=\"kw-ci\">contention physique</span> = dernier recours, durée limitée</li></ul>"}]},"cards":[{"i":"26cc4e79b956","n":108,"o":"108-10","u":"Diagnostic positif","t":"Connaître les principaux diagnostics différentiels de la MA","q":"Quelles sont les principales causes de « démences » secondaires curables à rechercher systématiquement devant un syndrome démentiel ?","a":"<p>Les principales causes de « démences » secondaires curables, potentiellement réversibles, à toujours rechercher sont :</p><ul><li>L'<strong>hypothyroïdie</strong>.</li><li>La <strong>carence en vitamine B12 / folates</strong>.</li><li>La <strong>syphilis</strong> (neurosyphilis).</li><li>L'<strong>infection VIH</strong>.</li><li>Le <strong>méningiome frontal</strong>.</li><li>L'<strong>hématome sous-dural chronique</strong> (ralentissement psychomoteur, apathie, syndrome frontal).</li></ul>"},{"i":"56f37e13a62f","n":108,"o":"108-10","u":"Diagnostic positif","t":"Connaître les principaux diagnostics différentiels de la MA","q":"Quels sont les éléments distinctifs permettant de différencier une démence à corps de Lewy de la maladie d'Alzheimer (MA) ?","a":"<p>Devant un syndrome démentiel, la démence à corps de Lewy se distingue de la MA par :</p><ul><li>Des <strong>fluctuations</strong> cognitives.</li><li>Des <strong>hallucinations visuelles précoces</strong>.</li><li>Un <strong>syndrome parkinsonien akinéto-rigide</strong>.</li><li>Des troubles du comportement en <strong>sommeil paradoxal</strong>.</li><li>Une <strong>hypersensibilité aux neuroleptiques</strong>.</li></ul>"},{"i":"5c2273293f06","n":108,"o":"108-10","u":"Diagnostic positif","t":"Connaître les principaux diagnostics différentiels de la MA","q":"Quelles sont les causes à évoquer devant une démence rapidement progressive (installation en moins de 1 an) ?","a":"<p>Devant un syndrome démentiel d'installation en moins de 1 an, il faut évoquer :</p><ul><li>La <strong>maladie de Creutzfeldt-Jakob</strong> (qui associe syndrome cérébelleux, myoclonies, et conduit au décès en quelques mois).</li><li>Une <strong>encéphalite auto-immune ou paranéoplasique</strong>.</li></ul>"},{"i":"a37bfb60dbf1","n":108,"o":"108-10","u":"Diagnostic positif","t":"Connaître les principaux diagnostics différentiels de la MA","q":"Quels sont les éléments distinctifs permettant de différencier une démence fronto-temporale (DLFT) de la maladie d'Alzheimer (MA) ?","a":"<p>Devant un syndrome démentiel, la démence lobaire fronto-temporale (DLFT) se distingue de la MA par :</p><ul><li>Des <strong>troubles comportementaux précoces</strong> (désinhibition, perte des convenances sociales, apathie, perte d'empathie).</li><li>Un <strong>syndrome dysexécutif</strong> prédominant.</li><li>Une <strong>aphasie progressive</strong>.</li><li>Une <strong>survenue plus précoce</strong>, vers 50-60 ans.</li></ul>"},{"i":"b0e91c3d5af3","n":108,"o":"108-10","u":"Diagnostic positif","t":"Connaître les principaux diagnostics différentiels de la MA","q":"Quels sont les éléments distinctifs d'une hydrocéphalie chronique de l'adulte, à différencier de la maladie d'Alzheimer (MA) ?","a":"<p>L'hydrocéphalie chronique de l'adulte se caractérise par la <strong>triade d'Hakim et Adams</strong>, comprenant :</p><ul><li>Des <strong>troubles de la marche</strong>.</li><li>Des <strong>troubles cognitifs</strong>.</li><li>Des <strong>troubles vésico-sphinctériens</strong>.</li></ul><p>C'est une <strong>cause curable</strong> de démence.</p>"},{"i":"f8f592b4e864","n":108,"o":"108-10","u":"Diagnostic positif","t":"Connaître les principaux diagnostics différentiels de la MA","q":"Quels sont les éléments distinctifs permettant de différencier une démence vasculaire de la maladie d'Alzheimer (MA) ?","a":"<p>Devant un syndrome démentiel, la démence vasculaire se distingue de la MA par :</p><ul><li>Un <strong>déclin brutal</strong> ou en « marche d'escalier ».</li><li>La présence de <strong>séquelles focales</strong>.</li><li>La mise en évidence de <strong>lacunes et hypersignaux de la substance blanche à l'IRM</strong>.</li><li>Elle est la <strong>deuxième cause de démence</strong>.</li></ul>"},{"i":"0c74e2195d30","n":108,"o":"108-11","u":"Prise en charge","t":"Connaître les principes de prise en charge non médicamenteuse de la MA, y compris l’aide des réseaux ville-hôpital","q":"Quels sont les axes de la prise en charge non médicamenteuse de la maladie d'Alzheimer visant la stabilisation des troubles neurocognitifs (TNC) ?","a":"La stabilisation des TNC repose sur :<ul><li>La <strong>rééducation cognitive</strong> (remédiation cognitive) avec un <strong>orthophoniste</strong>.</li><li>La <strong>réhabilitation cognitive</strong> pour maintenir ou restaurer l'autonomie.</li><li>La <strong>stimulation cognitive</strong>.</li></ul>"},{"i":"21801ac7b3cc","n":108,"o":"108-11","u":"Prise en charge","t":"Connaître les principes de prise en charge non médicamenteuse de la MA, y compris l’aide des réseaux ville-hôpital","q":"Quand l'institutionnalisation est-elle envisagée pour un patient atteint de la maladie d'Alzheimer et quelles structures sont concernées ?","a":"L'institutionnalisation est envisagée lorsque <strong>le maintien à domicile devient impossible</strong>. Les structures concernées sont :<ul><li>Les <strong>Maisons de Retraite Médicalisées (EHPAD)</strong>.</li><li>Les <strong>services de long séjour</strong>.</li></ul>"},{"i":"74ea1bd7daa2","n":108,"o":"108-11","u":"Prise en charge","t":"Connaître les principes de prise en charge non médicamenteuse de la MA, y compris l’aide des réseaux ville-hôpital","q":"Quels sont les principaux réseaux et structures ville-hôpital intervenant dans la prise en charge non médicamenteuse de la maladie d'Alzheimer selon le degré d'autonomie ?","a":"Les réseaux ville-hôpital incluent :<ul><li>Les <strong>Équipes Spécialisées Alzheimer (ESA) à domicile</strong> pour les formes légères à modérées.</li><li>Les <strong>centres d'accueil de jour</strong> pour la stimulation cognitive.</li><li>Les dispositifs <strong>MAIA</strong> (Méthode d'Action pour l'Intégration des services d'aide et de soins dans le champ de l'Autonomie) en cas de perte d'autonomie ou de situation complexe (sujet seul, refus de soins).</li></ul>"},{"i":"af47e7752521","n":108,"o":"108-11","u":"Prise en charge","t":"Connaître les principes de prise en charge non médicamenteuse de la MA, y compris l’aide des réseaux ville-hôpital","q":"Quelles sont les différentes aides humaines, financières et la protection juridique disponibles dans le cadre de la prise en charge non médicamenteuse de la maladie d'Alzheimer ?","a":"<ul><li><strong>Aides humaines</strong> : aide à domicile, soutien logistique des aidants.</li><li><strong>Aides financières</strong> : prise en charge à <strong>100 % au titre de l'ALD 15</strong>, <strong>Allocation Personnalisée d'Autonomie (APA)</strong> selon grille AGGIR (> 60 ans), <strong>Prestation de Compensation du Handicap (PCH)</strong> (< 60 ans).</li><li><strong>Protection juridique</strong> : mesures médico-légales (sauvegarde de justice, tutelle, habilitation familiale) selon le degré de perte d'autonomie.</li></ul>"},{"i":"f0442eddf177","n":108,"o":"108-11","u":"Prise en charge","t":"Connaître les principes de prise en charge non médicamenteuse de la MA, y compris l’aide des réseaux ville-hôpital","q":"Comment les aidants d'une personne atteinte de la maladie d'Alzheimer sont-ils soutenus dans la prise en charge non médicamenteuse ?","a":"Le soutien aux aidants inclut :<ul><li>L'<strong>information, le soutien et l'accompagnement</strong> des proches.</li><li>Les <strong>plateformes d'accompagnement et de répit</strong>.</li><li>Les <strong>associations de familles</strong>.</li><li>La <strong>prévention de l'épuisement</strong> de l'aidant.</li></ul>"},{"i":"05af1a6cfd1b","n":108,"o":"108-15","u":"Contenu multimédia","t":"Tomodensitométrie d’un HSD chronique","q":"Comment identifier un hématome sous-dural (HSD) chronique à la TDM cérébrale concernant sa localisation ?","a":"<p>Un HSD chronique se présente comme une <strong>collection extra-axiale</strong> (extra-parenchymateuse) située dans l'<strong>espace sous-dural</strong>, entre la dure-mère et l'arachnoïde.</p>"},{"i":"75969baea9c1","n":108,"o":"108-15","u":"Contenu multimédia","t":"Tomodensitométrie d’un HSD chronique","q":"Quels sont les effets de masse et les signes associés à rechercher pour confirmer un hématome sous-dural chronique à la TDM cérébrale ?","a":"<ul><li><strong>Effet de masse :</strong> On observe un <strong>effacement des sillons corticaux</strong> en regard, une <strong>compression du ventricule latéral homolatéral</strong>, et une <strong>déviation de la ligne médiane</strong> (engagement sous-falcoriel si > 5 mm).</li><li><strong>Signes associés :</strong> Une <strong>atrophie cortico-sous-corticale</strong> sous-jacente est fréquente chez le sujet âgé, ainsi que la présence de <strong>cloisons de fibrine</strong> (HSD multi-cloisonné).</li></ul>"},{"i":"88a29fbe81b2","n":108,"o":"108-15","u":"Contenu multimédia","t":"Tomodensitométrie d’un HSD chronique","q":"Quel est le piège classique concernant l'hématome sous-dural chronique chez le sujet âgé ?","a":"<p>Chez le sujet âgé sous <strong>anticoagulant</strong> ou <strong>éthylique chronique</strong>, un hématome sous-dural chronique peut survenir <strong>sans traumatisme rapporté</strong>. Il est essentiel de rechercher systématiquement un HSD chronique par TDM cérébrale devant toute <strong>confusion</strong> ou <strong>syndrome frontal</strong> d'apparition récente.</p>"},{"i":"9fafee092f20","n":108,"o":"108-15","u":"Contenu multimédia","t":"Tomodensitométrie d’un HSD chronique","q":"Quelle est l'apparence caractéristique d'un hématome sous-dural chronique à la TDM cérébrale concernant sa forme et sa densité ?","a":"<ul><li><strong>Forme :</strong> Il a un aspect <strong>« en croissant »</strong>, concave vers le parenchyme cérébral.</li><li><strong>Densité :</strong> À la phase chronique, il est <strong>hypodense</strong> (10-30 UH). Un aspect mixte <strong>hypo/hyperdense</strong> avec un niveau liquide-liquide peut être observé en cas de resaignement (hématome sous-dural aigu sur chronique).</li></ul>"},{"i":"2da815d012fc","n":108,"o":"108-2","u":"Définition","t":"Connaître la définition d’une confusion et d’une démence","q":"Quels sont les deux critères majeurs définissant une démence (trouble neurocognitif majeur) ?","a":"<ul><li>Une <strong>altération durable d'au moins une fonction cognitive</strong> (mémoire, attention, langage, jugement) et/ou comportementale (personnalité, affects, conduites sociales), évoluant depuis <strong>plus de 6 mois</strong>.</li><li>Une <strong>altération de l'autonomie</strong> dans la vie quotidienne, induite par la sévérité de ces troubles.</li></ul>"},{"i":"431c2002a71f","n":108,"o":"108-2","u":"Définition","t":"Connaître la définition d’une confusion et d’une démence","q":"Quelle est la définition clinique d'une confusion mentale ou syndrome confusionnel ?","a":"<p>La confusion mentale est caractérisée par une <strong>altération modérée de la vigilance</strong> entraînant une désorganisation globale de la pensée et des fonctions cognitives. Elle est la conséquence de troubles attentionnels majeurs.</p>"},{"i":"64b501bf5c56","n":108,"o":"108-2","u":"Définition","t":"Connaître la définition d’une confusion et d’une démence","q":"Une confusion mentale peut-elle survenir chez un patient atteint de démence ?","a":"<p>Oui, une confusion mentale peut <strong>révéler</strong> ou <strong>émailler</strong> l'évolution d'un syndrome démentiel. Les deux ne s'excluent pas et la survenue d'un épisode confusionnel chez un sujet âgé impose une réévaluation cognitive à distance.</p>"},{"i":"6e03019b6c2e","n":108,"o":"108-2","u":"Définition","t":"Connaître la définition d’une confusion et d’une démence","q":"Comment l'installation et la réversibilité distinguent-elles la confusion mentale de la démence ?","a":"<ul><li>La <strong>confusion mentale</strong> a une installation <strong>aiguë</strong> et est potentiellement <strong>réversible</strong>.</li><li>La <strong>démence</strong> a une installation <strong>progressive</strong> et est généralement <strong>irréversible</strong>.</li></ul>"},{"i":"143d81d81a72","n":108,"o":"108-5","u":"Diagnostic positif","t":"Savoir rechercher les causes de la confusion mentale","q":"Dans quels contextes un EEG est-il indiqué face à une confusion mentale ?","a":"<ul><li>Suspicion de <strong>confusion post-critique</strong> d'une épilepsie</li><li>Dépistage d'<strong>épilepsies infracliniques</strong> si le reste du bilan est négatif</li></ul>"},{"i":"34a193c67c41","n":108,"o":"108-5","u":"Diagnostic positif","t":"Savoir rechercher les causes de la confusion mentale","q":"Quels sont les facteurs prédisposants à la confusion mentale chez le sujet âgé ?","a":"<ul><li><strong>Âge ≥ 80 ans</strong></li><li>Antécédents de confusion (notamment post-opératoire)</li><li>Troubles NeuroCognitifs Majeurs (TNCM) ou troubles cognitifs chroniques</li><li>Immobilisation (aggravée par la contention)</li><li>Déficits sensoriels (visuel ou auditif)</li><li>Comorbidités multiples</li><li>Dénutrition</li><li>Polymédication</li><li>Troubles de l'humeur (état dépressif)</li></ul>"},{"i":"47f6e131b932","n":108,"o":"108-5","u":"Diagnostic positif","t":"Savoir rechercher les causes de la confusion mentale","q":"Dans quels contextes une TDM cérébrale est-elle indiquée en première intention face à une confusion mentale ?","a":"<ul><li>Présence d'un <strong>signe de localisation</strong></li><li>Suspicion d'<strong>hémorragie sous-arachnoïdienne (HSA)</strong></li><li><strong>Traumatisme crânien</strong> même mineur</li><li>Chute dans des circonstances peu claires</li></ul>"},{"i":"7b71e04afdc7","n":108,"o":"108-5","u":"Diagnostic positif","t":"Savoir rechercher les causes de la confusion mentale","q":"Quel bilan de première intention doit être réalisé systématiquement pour rechercher les causes d'une confusion mentale chez le sujet âgé ?","a":"<ul><li><strong>SaO2</strong> (saturation en oxygène)</li><li><strong>NFS</strong> (Numération Formule Sanguine)</li><li><strong>CRP</strong> (Protéine C réactive)</li><li><strong>Créatininémie</strong></li><li><strong>Ionogramme sanguin</strong></li><li><strong>Calcémie</strong></li><li><strong>Glycémie</strong></li><li><strong>Protides totaux</strong></li><li><strong>Bandelette urinaire</strong></li><li><strong>ECG</strong> (Électrocardiogramme)</li><li>Bilan hépatique (ajout du CEN)</li><li>Bilan d'hémostase (ajout du CEN)</li><li>Radiographie thoracique (ajout du CEN)</li></ul>"},{"i":"a130f1f8f6a7","n":108,"o":"108-5","u":"Diagnostic positif","t":"Savoir rechercher les causes de la confusion mentale","q":"Quels sont les facteurs précipitants de la confusion mentale chez le sujet âgé et quelle est la conséquence de leur correction ?","a":"<p>Les facteurs précipitants sont souvent <strong>multiples</strong> chez le sujet âgé et peuvent correspondre à <strong>toute situation aiguë, iatrogène ou pathologique</strong>. Leur correction représente souvent le <strong>seul traitement nécessaire à la guérison</strong> de l'épisode confusionnel.</p>"},{"i":"c5a75045cf61","n":108,"o":"108-5","u":"Diagnostic positif","t":"Savoir rechercher les causes de la confusion mentale","q":"Dans quels contextes une ponction lombaire est-elle indiquée en première intention face à une confusion mentale ?","a":"<ul><li><strong>Fièvre sans autre point d'appel</strong></li><li>Présence d'un <strong>syndrome méningé</strong></li><li>Suspicion d'<strong>hémorragie sous-arachnoïdienne (HSA)</strong>, après réalisation d'une TDM cérébrale qui est négative.</li></ul>"},{"i":"ed0113fe0fb7","n":108,"o":"108-5","u":"Diagnostic positif","t":"Savoir rechercher les causes de la confusion mentale","q":"Quelle est la particularité de la démarche étiologique face à une confusion mentale chez le sujet âgé ?","a":"<p>La démarche étiologique chez le sujet âgé suit une approche en <strong>deux étapes</strong>, identifiant d'abord les <strong>facteurs prédisposants</strong>, puis les <strong>facteurs précipitants</strong>. Il est important de noter que plus la <strong>réserve cognitive est dégradée</strong>, moins le facteur précipitant a besoin d'être important pour déclencher la confusion.</p>"},{"i":"130970a3d6a5","n":108,"o":"108-6","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’un patient confus","q":"Quel est le délai de résolution attendu pour la confusion, même après traitement étiologique?","a":"<p>La confusion peut disparaître <strong>lentement</strong>, même après résolution de sa cause. Il faut faire preuve de <strong>patience</strong> avant d'évaluer complètement l'efficacité de la prise en charge.</p>"},{"i":"571d2a9fa6e0","n":108,"o":"108-6","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’un patient confus","q":"Quelle est l'approche initiale et les priorités de prise en charge pour un patient confus, d'après les principes thérapeutiques?","a":"<p>La confusion est une <strong>urgence diagnostique et thérapeutique</strong> nécessitant une <strong>hospitalisation</strong>. La démarche est en <strong>deux temps</strong> :</p><ul><li>Évaluer le <strong>retentissement vital</strong> à court terme (constantes) et traiter immédiatement les troubles vitaux (ex. état de choc).</li><li>Déterminer l'<strong>étiologie</strong>, car le traitement de la cause est la priorité absolue pour la guérison. En gériatrie, cela implique de corriger les facteurs précipitants.</li></ul>"},{"i":"cdbf16e00f25","n":108,"o":"108-6","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’un patient confus","q":"Quelles sont les mesures générales à privilégier systématiquement dans la prise en charge d'un patient confus?","a":"<ul><li><strong>Supprimer les traitements non indispensables</strong>, surtout les psychotropes (attention au sevrage brutal d'un psychotrope ancien, qui est confusiogène).</li><li>Diminuer la posologie des <strong>corticoïdes</strong>.</li><li>Maintenir l'<strong>hydratation et la nutrition</strong> (au besoin par voie parentérale).</li><li>Favoriser l'<strong>élimination</strong> (laxatifs, accès aux toilettes).</li><li>Assurer un <strong>environnement calme, sécurisant, suffisamment éclairé</strong>, si possible en chambre individuelle, avec des visites limitées aux référents.</li><li>Lutter contre l'<strong>isolement sensoriel</strong> (prothèses auditives, lunettes).</li><li>Maintenir une <strong>mobilité physique</strong>.</li><li>Restaurer les <strong>repères spatio-temporels</strong> (calendrier, horloge).</li></ul>"},{"i":"e19a2cc53235","n":108,"o":"108-6","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique d’un patient confus","q":"Quand et comment utiliser les traitements symptomatiques pour la confusion, et quels traitements éviter spécifiquement?","a":"<p>Les traitements symptomatiques sont d'un <strong>recours rare</strong> et la <strong>voie orale est privilégiée</strong> :</p><ul><li>Pour une <strong>anxiété majeure uniquement</strong> : Benzodiazépines à demi-vie courte à faible dose (<strong>oxazépam, alprazolam</strong>). <strong>À éviter</strong> : hydroxyzine, cyamémazine, halopéridol (composante anticholinergique).</li><li>Pour un <strong>délire/hallucinations avec agitation menaçante</strong> : Neuroleptique atypique per os (<strong>rispéridone ou olanzapine</strong>). <strong>Éviter les formes injectables</strong>. Le tiapride IM est en dernier recours.</li><li>Pour une <strong>maladie à corps de Lewy / Parkinson</strong> : les neuroleptiques habituels sont <strong>contre-indiqués</strong> (risque de syndrome malin). Utiliser la <strong>quétiapine</strong> (hors AMM) ou la <strong>clozapine</strong>.</li><li>La <strong>contention physique</strong> est un <strong>dernier recours</strong>, sur prescription médicale, de durée limitée, avec réévaluation pluriquotidienne. Elle aggrave l'agitation et l'angoisse.</li></ul>"},{"i":"11e0f775a104","n":108,"o":"108-8","u":"Diagnostic positif","t":"Connaître les manifestations cliniques de la MA aux différentes phases","q":"Décrivez les manifestations cliniques de la phase de démence très sévère de la maladie d'Alzheimer.","a":"<p>La phase de démence très sévère de la maladie d'Alzheimer, survenant après environ <strong>7-8 ans</strong>, est marquée par :</p><ul><li>Une <strong>perte d'autonomie totale</strong>.</li><li>Une <strong>non-reconnaissance des proches</strong>.</li><li>Une multitude de <strong>troubles du comportement</strong> (agitation, apathie, hallucinations visuelles, déambulation).</li><li>Des <strong>troubles de la déglutition</strong> et une <strong>dénutrition</strong>.</li><li>Des <strong>troubles sphinctériens</strong>.</li><li>Des <strong>troubles neurologiques</strong> comme l'épilepsie et les myoclonies.</li><li>Le patient est en <strong>état grabataire</strong>, conduisant au décès.</li><li>Le score MMSE est généralement <strong>&lt; 10</strong>.</li></ul>"},{"i":"1e47f8b3759c","n":108,"o":"108-8","u":"Diagnostic positif","t":"Connaître les manifestations cliniques de la MA aux différentes phases","q":"Quelles sont les caractéristiques cliniques de la phase prodromale (pré-démentielle) de la maladie d'Alzheimer ?","a":"<p>La phase prodromale de la maladie d'Alzheimer, ou trouble neurocognitif mineur, se caractérise par :</p><ul><li>Un patient <strong>autonome</strong>.</li><li>Une <strong>plainte mnésique</strong> prédominante, typiquement un « oubli à mesure » qui fait répéter le patient.</li><li>Une <strong>anosognosie</strong>, contrastant avec l'inquiétude de l'entourage.</li><li>Un trouble de la <strong>consolidation en mémoire épisodique</strong>.</li><li>Le score MMSE est généralement <strong>&gt; 20</strong>.</li></ul>"},{"i":"921ef6da2d52","n":108,"o":"108-8","u":"Diagnostic positif","t":"Connaître les manifestations cliniques de la MA aux différentes phases","q":"Quels sont les signes cliniques de la phase d'état (démence) de la maladie d'Alzheimer ?","a":"<p>La phase d'état de la maladie d'Alzheimer est caractérisée par :</p><ul><li>Une <strong>perte d'autonomie</strong> pour les activités de la vie quotidienne courantes (ex : gérer l'argent, utiliser le téléphone, conduire).</li><li>Une <strong>aggravation du trouble de la mémoire</strong>.</li><li>L'apparition d'un <strong>syndrome aphaso-apraxo-agnosique</strong>, avec notamment une <strong>apraxie idéo-motrice</strong> et une <strong>aphasie motrice</strong> (baisse de la fluence verbale sans trouble de la compréhension).</li><li>Le score MMSE est généralement compris entre <strong>10 et 20</strong>.</li></ul>"}]};